<!doctype html>
<html lang="id">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>@yield('title') — Awe Print</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
    <script>try{if(localStorage.getItem('theme')==='dark')document.documentElement.classList.add('dark')}catch(e){}</script>
    @vite(['resources/css/app.css','resources/js/app.js'])
    <style>
        :root{--auth-bg:#080b0a;--auth-panel:#101512;--auth-ink:#f4f7ef;--auth-muted:#8e9b91;--auth-line:rgba(255,255,255,.1);--auth-lime:#b9f34b;--auth-cyan:#48e5da}
        .auth-page{min-height:100vh;background:var(--auth-bg);color:var(--auth-ink);font-family:'DM Sans',sans-serif;overflow:hidden}.auth-display{font-family:'Manrope',sans-serif}.auth-mono{font-family:'Space Mono',monospace}.auth-shell{height:100vh;min-height:100vh;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(460px,.72fr)}
        .auth-story{position:relative;display:flex;min-height:100vh;flex-direction:column;justify-content:space-between;padding:46px clamp(38px,5vw,78px);overflow:hidden;border-right:1px solid var(--auth-line);background:radial-gradient(circle at 80% 25%,rgba(72,229,218,.12),transparent 34%),radial-gradient(circle at 20% 90%,rgba(185,243,75,.1),transparent 32%)}.auth-story:before{content:"";position:absolute;inset:0;opacity:.35;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(black,transparent 88%)}
        .auth-brand,.auth-copy,.auth-foot{position:relative;z-index:2}.auth-brand{display:flex;align-items:center;gap:12px;width:max-content}.auth-mark{position:relative;display:grid;width:44px;height:44px;place-items:center;border-radius:14px;background:var(--auth-lime);color:#10150d;font-weight:800;box-shadow:0 0 36px rgba(185,243,75,.2)}.auth-mark:after{content:"";position:absolute;inset:4px;border:1px solid rgba(0,0,0,.3);border-radius:10px}.auth-brand strong{display:block;font-size:14px}.auth-brand small{display:block;margin-top:2px;color:var(--auth-muted);font-size:9px;letter-spacing:.16em}.auth-copy{max-width:690px}.auth-live{display:flex;align-items:center;gap:10px;color:var(--auth-lime);font-size:10px;letter-spacing:.16em}.auth-live i{width:7px;height:7px;border-radius:50%;background:var(--auth-lime);animation:authPulse 1.7s infinite}.auth-copy h1{margin:25px 0 0;font-size:clamp(48px,5.8vw,84px);line-height:.98;letter-spacing:-.06em}.auth-copy h1 span{color:transparent;-webkit-text-stroke:1px rgba(244,247,239,.5)}.auth-copy>p{max-width:610px;margin:27px 0 0;color:var(--auth-muted);font-size:16px;line-height:1.75}.auth-stats{display:flex;gap:12px;margin-top:38px}.auth-stat{min-width:130px;padding:14px 16px;border:1px solid var(--auth-line);border-radius:15px;background:rgba(255,255,255,.035);backdrop-filter:blur(12px)}.auth-stat b{display:block;font-size:14px}.auth-stat small{display:block;margin-top:4px;color:var(--auth-muted);font-size:9px;letter-spacing:.08em}.auth-foot{display:flex;align-items:center;gap:14px;color:#657169;font-size:10px}.auth-foot:before{content:"";width:42px;height:1px;background:var(--auth-line)}
        .auth-orb{position:absolute;border-radius:50%;pointer-events:none}.auth-orb-a{width:390px;height:390px;right:-140px;top:15%;border:1px solid rgba(72,229,218,.18);box-shadow:inset 0 0 90px rgba(72,229,218,.06);animation:authOrbit 10s ease-in-out infinite}.auth-orb-b{width:110px;height:110px;right:15%;top:18%;background:radial-gradient(circle at 35% 30%,var(--auth-lime),rgba(185,243,75,.03) 68%);filter:blur(1px);animation:authFloat 6s ease-in-out infinite}.auth-ticket{position:absolute;z-index:1;right:8%;bottom:13%;width:210px;padding:16px;border:1px solid var(--auth-line);border-radius:16px;background:rgba(15,21,17,.72);backdrop-filter:blur(16px);box-shadow:0 25px 60px rgba(0,0,0,.3);transform:rotate(-5deg);animation:authFloat 7s 1s ease-in-out infinite}.auth-ticket-top{display:flex;justify-content:space-between;color:var(--auth-muted);font-size:9px}.auth-ticket strong{display:block;margin-top:16px;font-size:13px}.auth-progress{height:4px;margin-top:12px;border-radius:8px;background:#263028;overflow:hidden}.auth-progress i{display:block;width:78%;height:100%;background:linear-gradient(90deg,var(--auth-lime),var(--auth-cyan));animation:authProgress 3s ease-in-out infinite}
        .auth-panel{position:relative;display:flex;align-items:center;justify-content:center;height:100vh;min-height:100vh;padding:45px clamp(28px,4vw,64px);background:linear-gradient(145deg,rgba(255,255,255,.045),rgba(255,255,255,.012));overflow-y:auto}.auth-panel:before{content:"";position:absolute;inset:0;background:radial-gradient(500px circle at 100% 0%,rgba(185,243,75,.07),transparent 60%);pointer-events:none}.auth-card{position:relative;width:100%;max-width:430px;animation:authEnter .8s cubic-bezier(.2,.8,.2,1) both}.auth-mobile-brand{display:none}.auth-kicker{color:var(--auth-lime);font-size:10px;letter-spacing:.17em;text-transform:uppercase}.auth-card h2{margin:13px 0 0;font-size:34px;letter-spacing:-.045em}.auth-intro{margin:10px 0 0;color:var(--auth-muted);font-size:14px;line-height:1.65}.auth-form{display:grid;gap:18px;margin-top:32px}.auth-field label{display:block;margin-bottom:8px;color:#d9dfda;font-size:12px;font-weight:600}.auth-input-wrap{position:relative}.auth-input{width:100%;height:52px;border:1px solid var(--auth-line)!important;border-radius:14px!important;background:rgba(255,255,255,.035)!important;padding:0 16px!important;color:var(--auth-ink)!important;font-size:14px!important;outline:none!important;box-shadow:inset 0 1px rgba(255,255,255,.025)!important;transition:.25s!important}.auth-input.has-action{padding-right:52px!important}.auth-input::placeholder{color:#5f6b62!important}.auth-input:hover{border-color:rgba(185,243,75,.28)!important}.auth-input:focus{border-color:var(--auth-lime)!important;box-shadow:0 0 0 4px rgba(185,243,75,.08),0 18px 35px rgba(0,0,0,.16)!important;transform:translateY(-1px)}.auth-toggle{position:absolute;right:8px;top:7px;display:grid;width:38px;height:38px;place-items:center;border:0;border-radius:10px;background:transparent;color:var(--auth-muted);cursor:pointer}.auth-toggle:hover{background:rgba(255,255,255,.06);color:var(--auth-lime)}.auth-error{margin:7px 0 0;color:#fb7185;font-size:11px}.auth-options{display:flex;align-items:center;justify-content:space-between;gap:15px;color:var(--auth-muted);font-size:12px}.auth-check{display:flex;align-items:center;gap:9px;cursor:pointer}.auth-check input{width:16px;height:16px;accent-color:var(--auth-lime)}.auth-submit{position:relative;display:flex;width:100%;height:53px;align-items:center;justify-content:center;gap:10px;border:0;border-radius:14px;background:var(--auth-lime);color:#11160e;font-weight:800;cursor:pointer;overflow:hidden;box-shadow:0 15px 38px rgba(185,243,75,.13);transition:.25s}.auth-submit:before{content:"";position:absolute;inset:-2px;background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.55),transparent 70%);transform:translateX(-110%);transition:.7s}.auth-submit:hover{transform:translateY(-3px);box-shadow:0 20px 45px rgba(185,243,75,.2)}.auth-submit:hover:before{transform:translateX(110%)}.auth-submit:active{transform:scale(.985)}.auth-switch{margin-top:25px;padding-top:22px;border-top:1px solid var(--auth-line);text-align:center;color:var(--auth-muted);font-size:13px}.auth-switch a{color:var(--auth-lime);font-weight:700}.auth-back{display:inline-flex;align-items:center;gap:7px;margin-top:26px;color:#667269;font-size:11px}.auth-back:hover{color:var(--auth-ink)}.auth-alert{margin-top:20px;padding:13px 15px;border:1px solid rgba(251,113,133,.25);border-radius:13px;background:rgba(251,113,133,.08);color:#fda4af;font-size:12px}
        @keyframes authPulse{70%{box-shadow:0 0 0 12px rgba(185,243,75,0)}}@keyframes authOrbit{50%{transform:translate(-28px,20px) rotate(18deg)}}@keyframes authFloat{50%{transform:translateY(-18px) rotate(3deg)}}@keyframes authProgress{50%{width:96%}}@keyframes authEnter{from{opacity:0;transform:translateY(25px) scale(.985)}to{opacity:1;transform:none}}
        @media(max-width:1023px){.auth-page{overflow:auto}.auth-shell{display:block;height:auto}.auth-story{display:none}.auth-panel{height:auto;padding:36px 22px}.auth-mobile-brand{display:flex;margin-bottom:42px}.auth-card{max-width:500px}}@media(max-width:520px){.auth-panel{align-items:flex-start;padding-top:25px}.auth-mobile-brand{margin-bottom:32px}.auth-card h2{font-size:30px}.auth-form{margin-top:27px}.auth-stats{display:none}}@media(prefers-reduced-motion:reduce){.auth-page *{animation-duration:.01ms!important;animation-iteration-count:1!important}}
        /* Unified dashboard palette: navy, royal blue, emerald */
        :root{--auth-bg:#080f19;--auth-panel:#111827;--auth-ink:#f8fafc;--auth-muted:#94a3b8;--auth-line:rgba(148,163,184,.16);--auth-lime:#3b82f6;--auth-cyan:#10b981}
        .auth-story{background:radial-gradient(circle at 80% 25%,rgba(59,130,246,.16),transparent 34%),radial-gradient(circle at 20% 90%,rgba(16,185,129,.12),transparent 32%)}
        .auth-mark{color:#fff;box-shadow:0 0 36px rgba(59,130,246,.25)}
        .auth-live i{box-shadow:0 0 18px rgba(59,130,246,.35)}
        .auth-orb-a{border-color:rgba(59,130,246,.22);box-shadow:inset 0 0 90px rgba(59,130,246,.08)}
        .auth-orb-b{background:radial-gradient(circle at 35% 30%,var(--auth-cyan),rgba(16,185,129,.03) 68%)}
        .auth-panel:before{background:radial-gradient(500px circle at 100% 0%,rgba(59,130,246,.1),transparent 60%)}
        .auth-input:hover{border-color:rgba(59,130,246,.34)!important}.auth-input:focus{box-shadow:0 0 0 4px rgba(59,130,246,.1),0 18px 35px rgba(0,0,0,.16)!important}
        .auth-submit{color:#fff;box-shadow:0 15px 38px rgba(37,99,235,.2)}.auth-submit:hover{box-shadow:0 20px 45px rgba(37,99,235,.28)}
    </style>
</head>
<body class="auth-page"><main class="auth-shell"><section class="auth-story"><div class="auth-orb auth-orb-a"></div><div class="auth-orb auth-orb-b"></div><div class="auth-ticket"><div class="auth-ticket-top auth-mono"><span>JOB #0482</span><span>LIVE ●</span></div><strong class="auth-display">Production workflow</strong><div class="auth-progress"><i></i></div></div><a href="{{ url('/') }}" class="auth-brand"><span class="auth-mark auth-display">A</span><span><strong class="auth-display">AWE PRINT</strong><small class="auth-mono">DTF PRINTING STUDIO</small></span></a><div class="auth-copy"><div class="auth-live auth-mono"><i></i> Production system online</div><h1 class="auth-display">Create bold.<br><span>Track every step.</span></h1><p>Satu dashboard untuk mengirim desain, mengelola pembayaran, menyetujui preview, dan memantau produksi hingga selesai.</p><div class="auth-stats"><div class="auth-stat"><b class="auth-display">2 Cabang</b><small class="auth-mono">CONNECTED</small></div><div class="auth-stat"><b class="auth-display">Real-time</b><small class="auth-mono">ORDER STATUS</small></div><div class="auth-stat"><b class="auth-display">Private</b><small class="auth-mono">FILE STORAGE</small></div></div></div><div class="auth-foot auth-mono">SECURE CUSTOMER ACCESS</div></section><section class="auth-panel"><div class="auth-card"><a href="{{ url('/') }}" class="auth-brand auth-mobile-brand"><span class="auth-mark auth-display">A</span><span><strong class="auth-display">AWE PRINT</strong><small class="auth-mono">DTF PRINTING STUDIO</small></span></a>@yield('content')</div></section></main>
<script>document.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{const input=document.getElementById(button.dataset.togglePassword);if(!input)return;const visible=input.type==='text';input.type=visible?'password':'text';button.setAttribute('aria-label',visible?'Tampilkan password':'Sembunyikan password');button.querySelector('[data-eye]')?.classList.toggle('hidden',!visible);button.querySelector('[data-eye-off]')?.classList.toggle('hidden',visible)}));</script>
</body></html>
